const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解：设未知数为 x' },
      { kind: 'text', payload: '由题意列方程' },
      { kind: 'text', payload: '移项得' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var fs = 22;

    function mw(i, fallback) {
      var m = metrics && metrics[i];
      if (m) {
        if (typeof m.width === 'number') return m.width;
        if (typeof m.advanceWidth === 'number') return m.advanceWidth;
        if (typeof m.w === 'number') return m.w;
        if (m.size && typeof m.size.width === 'number') return m.size.width;
      }
      return fallback;
    }

    function rectPath(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }

    var margin = Math.round(Math.min(W, H) * 0.08);
    var pad = 18;
    var left = margin + 40;
    var right = W - margin;
    var top = margin + 96;
    var gap = 66;

    var widths = [
      mw(0, fs * 8.2),
      mw(1, fs * 5.6),
      mw(2, fs * 3.4)
    ];

    var paths = [];
    var nodes = [];

    paths.push({ id: 'paper', commands: rectPath(margin, margin, W - 2 * margin, H - 2 * margin) });
    nodes.push({ type: 'path', pathId: 'paper', fill: '#ffffff', stroke: '#c9d3e0' });

    for (var r = 0; r < 4; r++) {
      var ry = top + r * gap + 14;
      var y2 = Math.min(ry, H - margin - 8);
      paths.push({ id: 'rule' + r, commands: visualSdk.polyline([[left - pad, y2], [right - pad, y2]]) });
      nodes.push({ type: 'path', pathId: 'rule' + r, stroke: '#e2e9f1' });
    }

    var slotX = Math.min(left + widths[2] + 20, right - pad - 96);
    var slotY = top + 2 * gap - 16;
    paths.push({ id: 'slot', commands: rectPath(slotX, slotY, 96, 30) });
    nodes.push({ type: 'path', pathId: 'slot', fill: '#f6f8fb', stroke: '#e6ebf2' });

    nodes.push({ type: 'label', x: left, y: top - 8, text: '解：设未知数为 x', fontSize: fs, fill: '#1f2b3a' });
    nodes.push({ type: 'label', x: left, y: top + gap - 8, text: '由题意列方程', fontSize: fs, fill: '#1f2b3a' });
    nodes.push({ type: 'label', x: left, y: top + 2 * gap - 8, text: '移项得', fontSize: fs, fill: '#1f2b3a' });

    return {
      schemaVersion: 1,
      sceneId: 'fig-transcription-clean',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
